python3 -c "
import json

nodes = []
for f in ['/tmp/dcmp-r11-arch.json', '/tmp/dcmp-r11-feat-auth.json', '/tmp/dcmp-r11-feat-dashboard.json', '/tmp/dcmp-r11-feat-notification.json', '/tmp/dcmp-r11-feat-admin-report.json']:
    with open(f) as fh:
        nodes.append(json.load(fh))

# Check for cycles using DFS
adj = {}
for n in nodes:
    nid = n['graph_node_id']
    adj[nid] = n.get('depends_on', [])

WHITE, GRAY, BLACK = 0, 1, 2
color = {k: WHITE for k in adj}
has_cycle = False

def dfs(u):
    global has_cycle
    color[u] = GRAY
    for v in adj[u]:
        if v in color:
            if color[v] == GRAY:
                has_cycle = True
                return
            elif color[v] == WHITE:
                dfs(v)
    color[u] = BLACK

for u in adj:
    if color[u] == WHITE:
        dfs(u)

print(f'Nodes: {len(nodes)}')
print(f'Has cycle: {has_cycle}')
for n in nodes:
    print(f'  {n[\"graph_node_id\"]} ({n[\"artifact_kind\"]}) -> depends_on: {n.get(\"depends_on\", [])}')

# Count edges
edges = sum(len(n.get('depends_on', [])) for n in nodes)
print(f'Total edges: {edges}')

# Check task contamination
tasks = [n for n in nodes if n['artifact_kind'] == 'task']
print(f'Task nodes: {len(tasks)}')

# Build preview graph
preview = {'graph_revision': 1, 'nodes': nodes}
print(json.dumps(preview, ensure_ascii=False, indent=2))
" > /Users/dm/orca/workspaces/HarnessHub/wt-19/eval-log/dev-graph/live-trial-fixtures/dcmp-r11-none/eval-log/macro-preview.json 2>&1

